module.exports = /*#__PURE__*/JSON.parse('{"faqs":[{"id":"seo-timing","question":"How long does it take to see results from SEO?","answer":"SEO is a long-term strategy. Most businesses start seeing meaningful traffic increases within 3-6 months, with substantial lead growth by 6-12 months. We focus on quick wins like site speed and local listings while building content that compounds over time."},{"id":"ad-disapprovals","question":"Why do my Google Ads keep getting disapproved?","answer":"Ads get disapproved for policy violations such as misleading claims or problematic landing pages. As a Google-certified agency we ensure every campaign adheres to platform policies, minimizing rejections and keeping your ads running profitably."},{"id":"marketing-budget","question":"How much should I spend on digital marketing?","answer":"Most businesses allocate 3-5% of annual revenue for ongoing marketing, increasing to 8-10% during growth phases. Starting at $2,500 to $5,000 per month typically allows for comprehensive SEO and PPC campaigns. We set realistic goals and scale as your ROI improves."},{"id":"nationwide-service","question":"Do you work with businesses outside Texas and California?","answer":"Yes, absolutely. We serve businesses across the entire United States. Whether you are in New York, Florida, Illinois, or anywhere else, our digital marketing strategies work in any market."},{"id":"multi-location","question":"Can you handle multi-location or franchise campaigns?","answer":"Yes. We specialize in multi-location marketing, creating separate local landing pages and geo-targeted campaigns for each branch so every location performs at its best."},{"id":"roi-measurement","question":"How do you measure and report marketing ROI?","answer":"We track Cost Per Acquisition and Customer Lifetime Value to calculate real ROI. Monthly reports tie leads and revenue back to each channel — organic, paid, and referral — so you know exactly which efforts drive profit."}]}');

